		let
		  // Load raw workspace data from the base environment query
		  Source = #"Base Power BI Workspaces",
		    // Sanitize workspace names by removing special characters
		    #"Invoked Custom Function" = Table.AddColumn(Source, "Clean Name", each #"Clean Name"([WorkspaceName]), type text),
		    // Drop the original unsanitized workspace name column
		    #"Removed Columns" = Table.RemoveColumns(#"Invoked Custom Function",{"WorkspaceName"}),
		    // Rename the cleaned name back to WorkspaceName
		    #"Renamed Columns" = Table.RenameColumns(#"Removed Columns",{{"Clean Name", "WorkspaceName"}}),
		        // Add a sequential index for ordering workspaces
		        #"Added Index" = Table.AddIndexColumn(#"Renamed Columns", "Workspace Index", 1, 1, Int64.Type)
		in
		    #"Added Index"
